// =====================================================================
//  Réglages du boss Nasu Samouraï — plop2point0 (id 135146), attaquant Force (zones) — LeekScript 4
//  (IA en ligne « force_nasu », même nom que ce fichier) BIBLIOTHÈQUE incluse par « force » après
//  « force_grp » : ne pas assigner seule. L'aiguillage de force.leek appelle n_setup() puis g_main()
//  dès qu'un ennemi s'appelle « nasu_… », avant le test de combat de groupe.
//  Ordre de cible : Rōnin, Élèves, Guerriers, Samouraï depuis le 2026-10-06 (avant : Élèves d'abord, choix du 2026-10-05,
//  après les défaites 53979465 et 53979576). L'ordre s'applique parmi les ennemis qui peuvent
//  frapper un allié au prochain tour (filtre de g_focusOf) : on ne court pas après un Élève à
//  15 cases pendant que le Samouraï est au contact.
//  Mêmes noms préfixés n_ dans les trois fichiers Nasu ; seul le bloc de rôle de n_setup diffère.
// =====================================================================

global n_VERSION = "N-2026-10-06d";

// combat contre le boss Nasu : un ennemi nommé « nasu_… » (nom renvoyé par getName, vu dans les logs)
function n_isNasu() {
	for (var e in getAliveEnemies()) {
		var nm = getName(e);
		if (nm != null && indexOf(nm, "nasu_") == 0) return true;
	}
	return false;
}

function n_setup() {
	// Rōnin d'abord (2026-10-06, accord de l'éleveur) : 800 à 1 100 dégâts par tour contre 110 à 160 pour un Élève ;
	// défaites 53986484-53986519 : Élève visé au T3, Rōnin intact au contact au T4, plop2point0 mort au T5-T6
	g_FOCUS_ORDER = ['nasu_ronin': 0, 'nasu_seito': 1, 'nasu_warrior': 2, 'nasu_samurai': 3];
	g_FOCUS_W = 1.0;                  // toute l'équipe sur la même cible
	g_CHEST_LOOT = true;              // un seul Nasu restant : coffre d'abord s'il reste assez de tours (g_chestTarget)
	// attaquant : inchangé hors cible ; un peu plus prudent, le Samouraï plonge (boss 53979576 : 548 au T8)
	g_KILL_RISK_FRAC = 0.7;
	if (getTurn() == 1) g_dbg("réglages Nasu v" + n_VERSION);
}
